const data = $input.first().json;
const totalAmount = Number(data.total_amount || 0);
const hasPriceMismatch = Boolean(data.has_price_mismatch);
const AUTO_APPROVE_LIMIT = 50000;

let auditStatus = 'passed';
let requiresHumanApproval = false;
let reason = 'Счёт соответствует договору и укладывается в лимит авто-одобрения.';

if (hasPriceMismatch) {
  auditStatus = 'price_mismatch';
  requiresHumanApproval = true;
  reason = 'Обнаружено расхождение цен с утверждённым прайс-листом контрагента.';
} else if (totalAmount > AUTO_APPROVE_LIMIT) {
  auditStatus = 'over_budget';
  requiresHumanApproval = true;
  reason = `Сумма счёта (${totalAmount} RUB) превышает порог автоматического одобрения (${AUTO_APPROVE_LIMIT} RUB).`;
}

return [{
  json: {
    audit_status: auditStatus,
    requires_human_approval: requiresHumanApproval,
    compliance_reason: reason
  }
}];
